import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import{At as i,Bt as a,Ct as o,Dt as s,Et as c,Ft as l,Gt as u,Ht as d,It as f,Jt as p,Kt as m,Lt as h,Mt as g,Nt as _,Ot as v,Pt as y,Rt as b,Tt as x,Ut as S,Vt as C,Wt as w,Xt as T,Yt as E,jt as D,kt as O,qt as k,wt as A,zt as j}from"./chunks/assets.BL_qWEMe.js";var M=JSON.parse(`{"title":"Fields","description":"","frontmatter":{},"headers":[],"relativePath":"product-config/fields.md","filePath":"product-config/fields.md"}`),N={name:`product-config/fields.md`},P=T+` 1x, `+E+` 2x`,F=p+` 1x, `+k+` 2x`,I=m+` 1x, `+u+` 2x`,L=w+` 1x, `+S+` 2x`,R=d+` 1x, `+C+` 2x`,z=a+` 1x, `+j+` 2x`,B=b+` 1x, `+h+` 2x`,V=f+` 1x, `+l+` 2x`,H=y+` 1x, `+_+` 2x`,U=g+` 1x, `+D+` 2x`,W=i+` 1x, `+O+` 2x`,G=v+` 1x, `+s+` 2x`,K=c+` 1x, `+x+` 2x`,q=A+` 1x, `+o+` 2x`;function J(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to “Fields”">​</a></h1><p>Product fields are rectangles that can contain texts</p><p>You can enable the fields feature and add the various fields to the designer.</p><p>In this example, we will add two text fields.</p><h2 id="adding-fields" tabindex="-1">Adding fields <a class="header-anchor" href="#adding-fields" aria-label="Permalink to “Adding fields”">​</a></h2><p>1️⃣ We start by adding the two fields by clicking the add button <img src="/webp/add-field-btn.jpg-90-1791641243256.webp" srcset="`+P+`" alt="Add field btn" title="" width="128" height="72" loading="lazy" style="width:64px;"></p><p><img src="/webp/product-fields.jpg-90-1791641243326.webp" srcset="`+F+`" alt="Product fields" title="" width="1590" height="1766" loading="lazy" style="width:795px;"></p><h2 id="editing-fields" tabindex="-1">Editing fields <a class="header-anchor" href="#editing-fields" aria-label="Permalink to “Editing fields”">​</a></h2><p>To edit a field, click the edit button</p><p><img src="/webp/edit-field-btn.jpg-90-1791641243295.webp" srcset="`+I+`" alt="Edit field btn" title="" width="634" height="434" loading="lazy" style="width:317px;"></p><p>This modal will be displayed</p><p><img src="/webp/edit-field-modal.jpg-90-1791641243295.webp" srcset="`+L+`" alt="Edit field modal" title="" width="668" height="1492" loading="lazy" style="width:334px;"></p><h2 id="text-field" tabindex="-1">Text field <a class="header-anchor" href="#text-field" aria-label="Permalink to “Text field”">​</a></h2><p>2️⃣ We enable the text field option on the first field and we set the label</p><p><img src="/webp/edit-text-field.jpg-90-1791641243296.webp" srcset="`+R+`" alt="Edit text field" title="" width="670" height="1492" loading="lazy" style="width:335px;"></p><p>The label will be be displayed like this</p><p><img src="/webp/field-label.jpg-90-1791641243297.webp" srcset="`+z+`" alt="Field label" title="" width="662" height="250" loading="lazy" style="width:331px;"></p><p>The text field will be displayed like this</p><p><img src="/webp/text-field-display.jpg-90-1791641243354.webp" srcset="`+B+`" alt="Text field display" title="" width="1838" height="702" loading="lazy" style="width:919px;"></p><h3 id="preferred-text-size" tabindex="-1">Preferred text size <a class="header-anchor" href="#preferred-text-size" aria-label="Permalink to “Preferred text size”">​</a></h3><p>By default, the text is scaled to fit the field, which means that its final size depends on how much text the customer types. If you want the text to be printed at a fixed physical size instead, set the <strong>Preferred text size (pt)</strong> option in the field settings.</p><p>The option is available on fields that have the <strong>Display as text field</strong> option enabled. Leave it at <code>0</code> to keep the automatic behaviour.</p><p>When a size is set:</p><ul><li>The text is rendered at that exact size in points, no matter how much text is entered</li><li>Long text wraps onto a new line at the field width instead of shrinking to fit</li></ul><p><img src="/webp/preferred-text-size.png-90-1791641243319.webp" srcset="`+V+`" alt="Preferred text size" title="" width="1294" height="660" loading="lazy" style="width:647px;"></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>The size is converted using the <a href="/product-config/real-size.html">real size</a> of the side, so make sure the real size is configured correctly, otherwise the printed text will not match the requested size.</p></div><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>The preferred size is ignored for vertical and curved texts. They fall back to the normal text rendering.</p></div><h2 id="single-item-only" tabindex="-1">Single item only <a class="header-anchor" href="#single-item-only" aria-label="Permalink to “Single item only”">​</a></h2><p>Enable this option if the field should hold only one design item.</p><p>When it is enabled, adding a text to the field replaces the one already there, and the duplicate button is hidden for that field. Leave it disabled to let customers stack several texts in the same field.</p><h2 id="rounded-field" tabindex="-1">Rounded field <a class="header-anchor" href="#rounded-field" aria-label="Permalink to “Rounded field”">​</a></h2><p>If we enable the rounded field option, we will have this display</p><p><img src="/webp/rounded-field.jpg-90-1791641243336.webp" srcset="`+H+`" alt="Rounded field" title="" width="716" height="668" loading="lazy" style="width:358px;"></p><h2 id="field-cost" tabindex="-1">Field cost <a class="header-anchor" href="#field-cost" aria-label="Permalink to “Field cost”">​</a></h2><p>3️⃣ Next, we set the extra cost for each field and choose whether to include the items cost that are inside the field.</p><p><img src="/webp/field-cost.jpg-90-1791641243296.webp" srcset="`+U+`" alt="Field cost" title="" width="644" height="280" loading="lazy" style="width:322px;"></p><h2 id="using-models" tabindex="-1">Using models <a class="header-anchor" href="#using-models" aria-label="Permalink to “Using models”">​</a></h2><p>You can enable models which are field templates that your customer can pick from.</p><p>First, enable the models like this</p><p><img src="/webp/models-switch.jpg-90-1791641243317.webp" srcset="`+W+`" alt="Models switch" title="" width="966" height="914" loading="lazy" style="width:483px;"></p><p>Then add any number of models by the clicking the add button</p><p><img src="/webp/add-model.jpg-90-1791641243257.webp" srcset="`+G+`" alt="Add model" title="" width="736" height="386" loading="lazy" style="width:368px;"></p><p>Then you can add fields to each model. The fields layout will be displayed directly.</p><p><img src="/webp/fields-preview.jpg-90-1791641243297.webp" srcset="`+K+`" alt="Fields preview" title="" width="1682" height="1066" loading="lazy" style="width:841px;"></p><p>The models will be displayed in the customer interface</p><p><img src="/webp/models-tab.png-90-1791641243318.webp" srcset="`+q+`" alt="Models tab" title="" width="1734" height="1276" loading="lazy" style="width:867px;"></p>`,46)]])}var Y=e(N,[[`render`,J]]);export{M as __pageData,Y as default};